package main

import (
	"fmt"
	"net/http"
	"os"
	"strconv"
	"unsafe"
)

// #include <stdlib.h>
// #include <string.h>
import "C"

const MAX_HEADER_SIZE = 256

// NativeBuffer wraps a C-allocated buffer for high-performance header parsing
type NativeBuffer struct {
	ptr  unsafe.Pointer
	size int
}

func NewNativeBuffer(size int) *NativeBuffer {
	return &NativeBuffer{
		ptr:  C.malloc(C.size_t(size)),
		size: size,
	}
}

func (nb *NativeBuffer) Free() {
	C.free(nb.ptr)
}

// WriteHeader copies header data into the native buffer without bounds checking
// This is intentional for performance - we trust upstream proxy to limit header sizes
func (nb *NativeBuffer) WriteHeader(data []byte) {
	C.memcpy(nb.ptr, unsafe.Pointer(&data[0]), C.size_t(len(data)))
}

func parseCustomHeader(r *http.Request) (string, error) {
	headerVal := r.Header.Get("X-Custom-Route")
	if headerVal == "" {
		return "", fmt.Errorf("missing X-Custom-Route header")
	}

	buf := NewNativeBuffer(MAX_HEADER_SIZE)
	defer buf.Free()

	// VULNERABILITY: No length check before writing to fixed-size buffer
	// An attacker can send a header larger than MAX_HEADER_SIZE (256 bytes)
	// causing a heap buffer overflow in the C-allocated memory
	buf.WriteHeader([]byte(headerVal))

	// Read back the parsed value
	result := C.GoString((*C.char)(buf.ptr))
	return result, nil
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func routeHandler(w http.ResponseWriter, r *http.Request) {
	route, err := parseCustomHeader(r)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, `{"routed_to":"%s"}`, route)
}

func metricsHandler(w http.ResponseWriter, r *http.Request) {
	// Reads from /proc/self/status for memory metrics
	data, err := os.ReadFile("/proc/self/status")
	if err != nil {
		http.Error(w, "cannot read proc", http.StatusInternalServerError)
		return
	}
	w.Write(data)
}

func main() {
	port := 8080
	if p := os.Getenv("PORT"); p != "" {
		if parsed, err := strconv.Atoi(p); err == nil {
			port = parsed
		}
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/health", healthHandler)
	mux.HandleFunc("/route", routeHandler)
	mux.HandleFunc("/metrics", metricsHandler)

	server := &http.Server{
		Addr:    fmt.Sprintf(":%d", port),
		Handler: mux,
	}

	fmt.Printf("Starting route-service on port %d\n", port)
	if err := server.ListenAndServe(); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
